# Regression tests for GeneralizedJacobian.jl; indentation is two spaces.
# Load the implementation first, then:
#   include("generalized_jacobian_test.jl")
#   GeneralizedJacobianTests.runtests(Main)
# Or run run_generalized_marking_tests.jl in a fresh Julia process.
#
# The suite installs no replacement implementation methods. Repeated punctures
# are deduplicated by place; distinct normalization branches remain distinct.
# They use the convention (evaluation_ratios(f), divisor(f)) = 0.
# Principal witnesses are compared via divisors, not by their scalar factor.
# Run selected groups with runtests(Main; groups=(:quotient, :branches)).

module GeneralizedJacobianTests

using Hecke
using Test

const GROUPS = (:bindings, :constructors, :validation, :points, :support,
  :arithmetic, :zero_data, :quotient, :structure, :branches, :infinity, :display)
const REJECTION = Union{ArgumentError, AssertionError}

function _field(eq)
  K, x = rational_function_field(QQBar, :gj_test_x; cached=false)
  _, Y = polynomial_ring(K, :gj_test_Y; cached=false)
  F, y = function_field(eq(x, Y), :gj_test_y; cached=false)
  return F, F(x), y
end

function _elliptic(api)
  F, x, y = _field((x, y) -> y^2 - x^3 - 1)
  C = api.punctured_marked_curve(F)
  J = api.jacobian(F)
  A, B = C(-1, 0), C(2, 3)
  R, S = C(0, 1), C(0, -1)
  puncts = api.GeometricPoint[A, B]
  D0 = divisor(R) - divisor(S)
  h = y + 2
  Dh = divisor(h)
  return (; F, x, y, C, J, A, B, R, S, puncts, D0, h, Dh)
end

function _generalized(api)
  f = _elliptic(api)
  G = api.generalized_jacobian(f.J, f.puncts)
  return merge(f, (; G, T=api.torus(G)))
end

function _components(api, P, G, t, D)
  @test P isa api.GeneralizedJacobianPoint
  @test Hecke.parent(P) === G
  @test Hecke.function_field(P) === Hecke.function_field(G)
  @test api.torus_part(P) == t
  @test divisor(api.jacobian_part(P)) == D
  @test Hecke.parent(api.torus_part(P)) === api.torus(G)
  @test Hecke.parent(api.jacobian_part(P)) === api.jacobian(G)
  @test P[1] === api.torus_part(P)
  @test P[2] === api.jacobian_part(P)
end

function _witness(api, P, expected; principal)
  result = api.iszero_with_data(P)
  @test result isa Tuple && length(result) == 2
  if result isa Tuple && length(result) == 2
    flag, f = result
    @test flag === expected
    if principal
      @test f isa Hecke.AbstractAlgebra.Generic.FunctionFieldElem
      if f isa Hecke.AbstractAlgebra.Generic.FunctionFieldElem
        @test Hecke.parent(f) === function_field(Hecke.parent(P))
        @test !iszero(f)
        @test divisor(f) == divisor(api.jacobian_part(P))
      end
    else
      @test f === nothing
    end
  end
  @test Base.iszero(P) === expected
  return result
end

function _bindings(api)
  @test api.parent === Hecke.parent
  @test api.iszero === Base.iszero
end

function _constructors(api)
  f = _elliptic(api)
  (; F, J, C, A, B, puncts) = f
  empty_puncts = api.GeometricPoint[]
  @test api.generalized_jacobian(J, empty_puncts) === J
  @test api.generalized_jacobian(J, api.GeometricPoint[A]) === J
  for ps in (empty_puncts, api.GeometricPoint[A])
    @test api.generalized_jacobian(F, ps) isa api.Jacobian
    @test function_field(api.generalized_jacobian(F, ps)) === F
  end

  for ps in (puncts, api.GeometricPoint[A, B, C(2, -3)])
    @testset "$(length(ps)) punctures" begin
      G = api.generalized_jacobian(J, ps)
      T = api.torus(G)
      L = api.dual(T)
      @test G isa api.GeneralizedJacobian
      @test api.jacobian(G) === J
      @test api.abelian_core(G) === J
      @test function_field(G) === F
      @test api.plane_equation(G) === api.plane_equation(J)
      @test api.punctures(G) == ps
      @test dim(T) == rank(L) == length(ps) - 1
      @test dim(G) == 1 + length(ps) - 1
      @test function_field(T) === function_field(L) === F
      @test all(degree(D) == 0 for D in basis(L))
      @test basis(L) == [divisor(P) - divisor(ps[end]) for P in ps[1:end-1]]
      @test all(!iszero(D) for D in basis(L))
    end
  end

  GF = api.generalized_jacobian(F, puncts)
  @test GF isa api.GeneralizedJacobian
  @test function_field(GF) === F
  @test dim(api.torus(GF)) == 1

  # Use the exact polynomial owned by the point parent: that is the current
  # polynomial-constructor contract, rather than equality across new rings.
  eq = api.plane_equation(C)
  GP = api.generalized_jacobian(eq, puncts)
  @test GP isa api.GeneralizedJacobian
  @test function_field(GP) === F
  @test dim(GP) == 2
  @test api.generalized_jacobian(eq, empty_puncts) isa api.Jacobian
  @test api.generalized_jacobian(eq, api.GeometricPoint[A]) isa api.Jacobian
end

function _validation(api)
  f, other = _elliptic(api), _elliptic(api)
  @test f.F !== other.F
  @testset "Fields are checked even with one puncture" begin
    @test_throws REJECTION api.generalized_jacobian(f.J, api.GeometricPoint[other.A])
    @test_throws REJECTION api.generalized_jacobian(f.F, api.GeometricPoint[other.A])
    @test_throws REJECTION api.generalized_jacobian(f.J, api.GeometricPoint[f.A, other.B])
    @test_throws REJECTION api.generalized_jacobian(f.F, api.GeometricPoint[f.A, other.B])
    @test_throws REJECTION api.generalized_jacobian(api.plane_equation(f.C), other.puncts)
  end
  @testset "Repeated punctures are deduplicated by place" begin
    # Reconstructed projective coordinates and another point parent for the
    # same field must represent the same puncture.
    C2 = api.punctured_marked_curve(f.F)
    for ps in (api.GeometricPoint[f.A, f.A],
      api.GeometricPoint[f.A, f.C(-2, 0, 2)],
      api.GeometricPoint[f.A, C2(-1, 0)])
      @test api.generalized_jacobian(f.J, ps) === f.J
    end

    ps = api.GeometricPoint[f.A, f.B, f.A]
    G = api.generalized_jacobian(f.J, ps)
    @test G isa api.GeneralizedJacobian
    @test length(ps) == 3
    if G isa api.GeneralizedJacobian
      @test api.jacobian(G) === f.J
      @test api.punctures(G) == api.GeometricPoint[f.A, f.B]
      @test dim(api.torus(G)) == 1
      @test basis(api.dual(api.torus(G))) == [divisor(f.A) - divisor(f.B)]
    end
  end
end

function _points(api)
  f = _generalized(api)
  (; G, J, T, D0, F) = f
  t, E = T(QQBarFieldElem[3]), J(D0)
  @testset "Checked constructors" begin
    for P in (api.generalized_jacobian_point(G, t, E), G(t, E))
      _components(api, P, G, t, D0)
      @test_throws BoundsError P[0]
      @test_throws BoundsError P[3]
    end
  end
  @testset "Convenience constructors" begin
    _components(api, G(t), G, t, trivial_divisor(F))
    _components(api, G(E), G, one(T), D0)
    _components(api, G(D0), G, one(T), D0)
  end
  @testset "Unchecked still checks parents" begin
    _components(api, G(t, E; check=false), G, t, D0)
    Gother = api.generalized_jacobian(J, f.puncts)
    Jother = api.jacobian(F)
    for check in (true, false)
      @test_throws REJECTION G(one(api.torus(Gother)), E; check)
      @test_throws REJECTION G(t, Jother(D0); check)
    end
    @test_throws REJECTION G(divisor(f.R))
  end
end

function _support(api)
  f = _generalized(api)
  (; G, J, T, F, D0) = f
  @test isnothing(G.puncture_divisor)
  Dp = api.puncture_divisor(G)
  @test Dp == divisor(f.A) + divisor(f.B)
  @test degree(Dp) == 2
  @test api.puncture_divisor(G) === Dp

  @testset "Signed divisors away from punctures are accepted" begin
    for D in (trivial_divisor(F), D0, -D0, 2D0, f.Dh, -f.Dh)
      @test iszero(gcd(lcm(D, -D), Dp))
      P = G(one(T), J(D))
      @test divisor(api.jacobian_part(P)) == D
    end
  end
  @testset "Either sign at a puncture is rejected" begin
    DA = divisor(f.A) - divisor(f.R)
    DB = divisor(f.B) - divisor(f.S)
    for D in (DA, -DA, DB, -DB, divisor(f.A) - divisor(f.B))
      @test !iszero(gcd(lcm(D, -D), Dp))
      @test_throws ArgumentError G(one(T), J(D))
      @test_throws ArgumentError G(J(D))
      @test_throws ArgumentError G(D)
      # Bypassing only support validation is an explicitly supported option.
      @test G(one(T), J(D); check=false) isa api.GeneralizedJacobianPoint
    end
  end
end

function _arithmetic(api)
  f = _generalized(api)
  (; G, J, T, D0, F) = f
  # Explicitly skip support recomputation here to isolate arithmetic from the
  # checked-constructor tests. Both representatives are independently disjoint.
  P = G(T(QQBarFieldElem[3]), J(D0); check=false)
  Q = G(T(QQBarFieldElem[5]), J(2D0); check=false)
  Z = zero(G)
  @testset "Representatives and component order" begin
    _components(api, Z, G, one(T), trivial_divisor(F))
    _components(api, zero(P), G, one(T), trivial_divisor(F))
    _components(api, P + Q, G, T(QQBarFieldElem[15]), 3D0)
    _components(api, -P, G, T(QQBarFieldElem[QQBar(1) / 3]), -D0)
    _components(api, P - Q, G, T(QQBarFieldElem[QQBar(3) / 5]), -D0)
  end
  @testset "Integer action" begin
    for n in (-3, -1, 0, 1, 2, 3)
      _components(api, n * P, G, T(QQBarFieldElem[QQBar(3)^n]), n * D0)
      @test P * n == n * P
    end
  end
  @testset "Group laws" begin
    @test P + Z == Z + P == P
    @test P + Q == Q + P
    @test (P + Q) + P == P + (Q + P)
    @test iszero(P - P)
    @test iszero(P + (-P))
    @test -(-P) == P
    @test 2 * (P + Q) == 2 * P + 2 * Q
    @test -3 * P == -(3 * P)
    @test P != Q
    Gother = api.generalized_jacobian(J, f.puncts)
    W = zero(Gother)
    @test Z != W
    @test_throws REJECTION P + W
    @test_throws REJECTION P - W
  end
end

function _zero_data(api)
  f = _generalized(api)
  (; G, J, T, D0) = f
  @testset "Identity and pure torus" begin
    _witness(api, zero(G), true; principal=true)
    _witness(api, G(T(QQBarFieldElem[3])), false; principal=true)
  end
  @testset "Nonprincipal component returns a pair" begin
    @test !iszero(J(D0))
    P = G(one(T), J(D0); check=false)
    @test isnothing(P[2].is_principal_with_data[1])
    _witness(api, P, false; principal=false)
    @test P[2].is_principal_with_data == (false, nothing)
    _witness(api, P, false; principal=false)
  end
  @testset "Nontrivial principal representative" begin
    P = G(T(QQBarFieldElem[QQBar(2) / 5]), J(f.Dh); check=false)
    @test !isone(P[1])
    @test !iszero(divisor(P[2]))
    _witness(api, P, true; principal=true)
    _witness(api, G(one(T), J(f.Dh); check=false), false; principal=true)
  end
end

function _quotient(api)
  f = _generalized(api)
  (; G, J, T, D0, y, Dh) = f
  @test evaluate(f.h, f.A) == 2
  @test evaluate(f.h, f.B) == 5
  P = G(T(QQBarFieldElem[3]), J(D0); check=false)
  Q = G(T(QQBarFieldElem[QQBar(6) / 5]), J(D0 + Dh); check=false)
  @test P == Q
  result = api.is_equal_with_data(P, Q)
  @test result isa Tuple && length(result) == 2
  if result isa Tuple && length(result) == 2
    @test result[1] === true
    @test divisor(result[2]) == -Dh
  end
  @test P != G(T(QQBarFieldElem[3]), J(D0 + Dh); check=false)

  # Jacobian torsion does not imply torsion of the same order in the extension.
  k = (y - 1) / (y + 1)
  @test divisor(k) == 3D0
  @test evaluate(k, f.A) / evaluate(k, f.B) == -2
  U = G(one(T), J(D0); check=false)
  @test 3U == G(T(QQBarFieldElem[-QQBar(1) / 2]))
  @test !iszero(3U)

  @testset "Two torus coordinates and pivot normalization" begin
    F, x, y = _field((x, y) -> y^2 - x^2 - 1)
    C = api.punctured_marked_curve(F)
    J = api.jacobian(F)
    ps = api.GeometricPoint[C(0, 1), C(0, -1), C(3, 5, 4)]
    H = api.generalized_jacobian(J, ps)
    T = api.torus(H)
    D = divisor(y + 2)
    r = T(QQBarFieldElem[QQBar(12) / 13, QQBar(4) / 13])
    @test dim(T) == 2
    @test iszero(H(r, J(D); check=false))
    @test H(T(QQBarFieldElem[5, 7]), J(D); check=false) ==
      H(T(QQBarFieldElem[QQBar(65) / 12, QQBar(91) / 4]))
  end
end

function _structure(api)
  f = _generalized(api)
  (; G, J, T) = f
  @test isnothing(G.structure_morphism)
  phi = api.extension_structure(G)
  @test phi isa api.MarkingMorphism
  @test api.domain(phi) === api.dual(T)
  @test api.codomain(phi) === J
  @test api.images(phi) isa Vector{api.JacobianPoint}
  @test length(api.images(phi)) == 1
  @test divisor(only(api.images(phi))) == divisor(f.A) - divisor(f.B)
  @test api.extension_structure(G) === phi
  api.assure_has_structure(G)
  @test G.structure_morphism === phi
  L = api.domain(phi)
  for n in (-2, 0, 1, 3)
    @test divisor(phi(L(n))) == n * (divisor(f.A) - divisor(f.B))
  end
end

function _branches(api)
  F, x, y = _field((x, y) -> y^2 - x^2 * (x + 1))
  C, J = api.punctured_marked_curve(F), api.jacobian(F)
  A, B = C(0, 0; index=1), C(0, 0; index=2)
  @test coordinates(A) == coordinates(B)
  @test api.place(A) != api.place(B)
  @test api.is_singular(A) && api.is_singular(B)
  @test api.generalized_jacobian(J,
    api.GeometricPoint[A, C(0, 0; index=1)]) === J
  G = api.generalized_jacobian(J, api.GeometricPoint[A, B])
  T = api.torus(G)
  h = y / x
  @test dim(T) == 1
  @test degree(api.puncture_divisor(G)) == 2
  @test Set([evaluate(h, A), evaluate(h, B)]) == Set(QQBarFieldElem[-1, 1])
  D = divisor(h)
  @test iszero(gcd(lcm(D, -D), api.puncture_divisor(G)))
  @test iszero(G(T(QQBarFieldElem[-1]), J(D)))
  @test !iszero(G(one(T), J(D)))
end

function _infinity(api)
  @testset "Smooth infinite puncture" begin
    F, x, y = _field((x, y) -> y^2 - x^2 - 1)
    C, J = api.punctured_marked_curve(F), api.jacobian(F)
    A, B = C(1, 1, 0), C(0, 1)
    G = api.generalized_jacobian(J, api.GeometricPoint[A, B])
    h = (x + 1) / (x + 2)
    @test is_infinite(A)
    @test evaluate(h, A) == 1
    @test evaluate(h, B) == QQBar(1) / 2
    @test iszero(G(api.torus(G)(QQBarFieldElem[2]), J(divisor(h))))
  end
  @testset "Distinct branches at singular infinity" begin
    F, x, y = _field((x, y) -> y^2 - x^4 - 1)
    C, J = api.punctured_marked_curve(F), api.jacobian(F)
    A, B = C(0, 1, 0; index=1), C(0, 1, 0; index=2)
    @test api.is_singular(A) && is_infinite(A)
    @test api.place(A) != api.place(B)
    G = api.generalized_jacobian(J, api.GeometricPoint[A, B])
    h = y / x^2
    @test Set([evaluate(h, A), evaluate(h, B)]) == Set(QQBarFieldElem[-1, 1])
    @test dim(api.torus(G)) == 1
    @test iszero(G(api.torus(G)(QQBarFieldElem[-1]), J(divisor(h))))
  end
end

function _display(api)
  f = _generalized(api)
  P = f.G(one(f.T), f.J(f.D0); check=false)
  @test P[2].is_principal_with_data === (nothing, nothing)
  old_structure, old_punctures = f.G.structure_morphism, f.G.puncture_divisor
  for (label, object) in (("variety", f.G), ("point", P))
    @testset "$label display uses its IO argument" begin
      # A temporary stream captures accidental print/println calls to stdout.
      # IOBuffer is not a supported redirect_stdout target in Julia.
      text, leaked = mktemp() do _, stream
        text = redirect_stdout(stream) do
          sprint(show, object)
        end
        flush(stream)
        seekstart(stream)
        return text, read(stream, String)
      end
      @test !isempty(strip(text))
      @test isempty(leaked)
      @test !isempty(sprint(show, MIME"text/plain"(), object))
    end
  end
  @test P[2].is_principal_with_data === (nothing, nothing)
  @test f.G.structure_morphism === old_structure
  @test f.G.puncture_divisor === old_punctures
end

"""
  runtests(api::Module=Main; groups=GROUPS)

Test an already-loaded implementation without adding or replacing its methods.
Each group has independent setup so one failed group does not stop the others.
"""
function runtests(api::Module=Main; groups=GROUPS)
  all(g -> g in GROUPS, groups) || throw(ArgumentError("Unknown test group"))
  @testset "GeneralizedJacobian" begin
    for group in groups
      @testset "$group" begin
        getfield(@__MODULE__, Symbol("_", group))(api)
      end
    end
  end
end

end # module
